public class Main {
    public static void main(String[] args) {
        String a = "Kaveri";
        String b = "Kaveri";                                   // same literal: the same pooled object
        String c = new String("Kaveri");                       // a new object, same text
        String d = new StringBuilder("Kav").append("eri").toString();  // built at runtime
        System.out.println("a == b: " + (a == b));
        System.out.println("a == c: " + (a == c) + ", a.equals(c): " + a.equals(c));
        System.out.println("a == d: " + (a == d) + ", a.equals(d): " + a.equals(d));
        Integer x = 127, y = 127, p = 128, q = 128;           // autoboxing uses a small cache
        System.out.println("127 == 127: " + (x == y) + ", 128 == 128: " + (p == q));
        System.out.println("128 equals 128: " + p.equals(q));
    }
}

import java.util.*;

public class Main {
    static final class Room {
        final String block;
        final int number;
        Room(String block, int number) { this.block = block; this.number = number; }

        @Override
        public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Room)) return false;
            Room r = (Room) o;
            return number == r.number && block.equals(r.block);
        }

        @Override
        public int hashCode() { return Objects.hash(block, number); }
    }

    static final class PlainRoom {                // no equals or hashCode
        final String block;
        final int number;
        PlainRoom(String block, int number) { this.block = block; this.number = number; }
    }

    public static void main(String[] args) {
        List<Room> booked = new ArrayList<>(List.of(new Room("A", 101)));
        List<PlainRoom> plain = new ArrayList<>(List.of(new PlainRoom("A", 101)));
        System.out.println("Room with equals, contains: " + booked.contains(new Room("A", 101)));
        System.out.println("PlainRoom, contains: " + plain.contains(new PlainRoom("A", 101)));
        Set<Room> set = new HashSet<>(List.of(new Room("B", 7), new Room("B", 7)));
        System.out.println("HashSet of two equal rooms has size " + set.size());
    }
}

