import java.io.*;
import java.util.*;

public class Main {
    static int countMatches(List<String> names, String query) {
        int count = 0;
        for (String n : names) if (n.equalsIgnoreCase(query)) count++;
        return count;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(in.readLine().trim());
        List<String> names = new ArrayList<>();
        for (int i = 0; i < n; i++) names.add(in.readLine().trim());
        String query = in.readLine().trim();
        System.out.println(countMatches(names, query));
    }
}
